def scr(sym, name):
    return {"title": f"Screener.in: {name} consolidated financials", "url": f"https://www.screener.in/company/{sym}/consolidated/"}


def fin(sym, eps, payout):
    f = {k: v for k, v in MEMBERS[sym]["financials"].items() if k != "cost_ok"}
    ok = MEMBERS[sym]["financials"].get("cost_ok", [True] * 5)
    for col in ("material_pct", "employee_pct", "manufacturing_pct", "other_cost_pct"):
        f[col] = [v if good else None for v, good in zip(f[col], ok)]
    f["expenses"] = [round(s - e) for s, e in zip(f["sales"], f["ebitda"])]
    f["eps"], f["div_payout"] = eps, payout
    return f


def news(date, title, cat, sent, impact, metrics, src, pl, bs, cf, doing, should):
    return {"date": date, "title": title, "category": cat, "sentiment": sent, "impact": impact, "metrics": metrics, "url": src["url"],
            "statement_impact": {"pl": pl, "bs": bs, "cf": cf, "doing": doing, "should": should}}


def problem(title, evidence, answer, investigate, service):
    return {"title": title, "evidence": evidence, "answer": answer, "investigate": investigate, "service": service}


def road(area, score, status, doing, gap, consultant, wave, sources=()):
    return {"area": area, "score": score, "status": status, "doing": doing, "gap": gap, "consultant": consultant, "wave": wave, "sources": list(sources)}


